import * as React from "react";
import Layout from "../components/layout";
import { graphql, PageProps } from "gatsby";
import data from "../data/data.json";
import { UserProfile } from "../interfaces";
import { useTranslation } from "gatsby-plugin-react-i18next";
import ImageModal, { type ImageItem } from "../components/ImageModal";
import Ornament from "../components/ornament";
import SEO from "../components/seo";

const userData: UserProfile = data;

const historicCollections = [
  {
    id: "brochure",
    icon: "/historic/brochure_icon.jpg",
    titleKey: "historic.brochure",
    files: [
      "2502980001-pi.jpg",
      "2502980002-pi.jpg",
      "2502980003-pi.jpg",
      "2502980004-pi.jpg",
      "2502980006-pi.jpg",
      "2502980007-pi.jpg",
      "2502980008-pi.jpg",
    ],
  },
  {
    id: "article",
    icon: "/historic/article_icon.jpg",
    titleKey: "historic.article",
    files: ["doc_2-1 1.jpg"],
  },
  {
    id: "advertising",
    icon: "/historic/advertising_icon.jpg",
    titleKey: "historic.advertising",
    files: ["doc_3-1.jpg", "doc_3-2.jpg", "doc_3-3.jpg", "doc_3-4.jpg"],
  },
];

const HistoricPage: React.FC<PageProps> = () => {
  const { t } = useTranslation();
  const [modalImages, setModalImages] = React.useState<ImageItem[]>([]);
  const [pendingOpen, setPendingOpen] = React.useState(false);
  const openModalRef = React.useRef<((startIndex?: number) => void) | null>(
    null
  );

  const openGallery = (images: ImageItem[]) => {
    setModalImages(images);
    setPendingOpen(true);
  };

  React.useEffect(() => {
    if (!pendingOpen || modalImages.length === 0) return;
    if (!openModalRef.current) return;
    openModalRef.current(0);
    setPendingOpen(false);
  }, [pendingOpen, modalImages]);

  const galleries = historicCollections.map((collection) => {
    const label = t(collection.titleKey) as string;
    const images = collection.files.map((file, index) => ({
      src: encodeURI(`/historic/${collection.id}/${file}`),
      alt: `${label} ${index + 1}`,
      caption: label,
    }));

    return { ...collection, label, images };
  });

  return (
    <Layout data={userData}>
      <SEO
        data={userData}
        titleKey="historic.metaTitle"
        descriptionKey="historic.metaDescription"
        pathname="/historic/"
        schemaType="ProfessionalService"
      />
      <section>
        <ImageModal
          images={modalImages}
          trigger={(open) => {
            openModalRef.current = open;
            return null;
          }}
        />

        <section className="text-terracota bg-beige px-12 py-6 mb-6 shadow-lg">

          <h2 className={styles.title}>{t("menu.historic")}</h2>

          <p className="text-center">Lorem ipsum dolor, sit amet consectetur adipisicing elit. Enim odit cupiditate velit quod harum. Hic explicabo expedita nesciunt quos, facilis sed culpa odio architecto quam nihil! Natus eum totam nobis?</p>

        <article className="grid gap-6 md:grid-cols-3 w-1/2 mx-auto mt-20">
          {galleries.map((gallery, index) => (
            <button
              key={gallery.id}
              type="button"
              className={`group text-terracota flex w-full flex-col items-center px-6 py-8 text-center transition duration-200 hover:-translate-y-1 `}
              onClick={() => openGallery(gallery.images)}
            >
              <img
                src={gallery.icon}
                alt={gallery.label}
                className="mb-4 h-80 w-auto object-contain"
              />
              <span className="body_mobile sm:body_desk">{gallery.label}</span>
            </button>
          ))}
        </article>



          <figure className="flex justify-center">
            <Ornament className="w-96 text-terracota/60 rotate-180" />
          </figure>
        </section>

      </section>
    </Layout>
  );
};

export default HistoricPage;

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

const styles = {
  title: "h2_mobile sm:h2_desk text-center mb-6",
};
